import {MODES,W,H,createRun,step,cyclePart,emptyProgress,sanitizeProgress,bankRun,upgrade,growthStats,clamp} from './sim.mjs';
import {draw} from './paint.mjs';
const $=id=>document.getElementById(id),canvas=$('arena'),ctx=canvas.getContext('2d');
const SAVE='pocketey-action-lab-v1';
let progress=emptyProgress(),storageOK=true;
try{progress=sanitizeProgress(JSON.parse(localStorage.getItem(SAVE)));}catch{storageOK=false;}
let selected=0,form=0,run=null,active=false,paused=false,showingResult=false,endHandled=false,lastFrame=0,hudClock=0;
const input={keys:new Set(),padKeys:new Set(),joy:{x:0,y:0},aim:null,action:false,lighten:false};
let joyPointer=null,joyOrigin=null,audio=null,sound=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function save(){try{localStorage.setItem(SAVE,JSON.stringify(progress));storageOK=true;}catch{storageOK=false;} $('save-note').textContent=storageOK?'進行と感想は、このブラウザーだけに保存。':'保存できません。この画面を閉じると進行が消えます。';}
function el(tag,attrs={},text=''){const e=document.createElement(tag);for(const[k,v]of Object.entries(attrs))k==='class'?e.className=v:e.setAttribute(k,v);if(text)e.textContent=text;return e;}
function tone(kind){if(!sound||!audio)return;const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=kind==='hurt'?'triangle':'sine';const f={guard:420,reflect:850,hit:250,throw:560,catch:350,eat:700,hurt:120,win:980,lose:100,dash:300,volley:160}[kind]||380;o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(f*(kind==='hurt'?.6:1.4),now+.08);g.gain.setValueAtTime(.025,now);g.gain.exponentialRampToValueAtTime(.001,now+.1);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+.11);}
function makeCards(){const parent=$('mode-grid');parent.replaceChildren();MODES.forEach((m,i)=>{const b=el('button',{class:'mode-card'+(i===selected?' active':''),'data-mode':m.id,type:'button','aria-pressed':String(i===selected),'aria-label':m.n+' '+m.title+'を選ぶ'});b.append(el('span',{class:'mode-no'},m.n+' / PLAYTEST'));const creature=el('span',{class:'mini-creature '+['slime','yoyo','robot','grow'][i],'aria-hidden':'true'},['••','','••','••'][i]);b.append(creature,el('strong',{},m.title),el('small',{},m.tag),el('span',{class:'mode-arrow','aria-hidden':'true'},'↗'));const p=progress.modes[m.id];if(p.plays||p.rating)b.append(el('span',{class:'played'},p.rating||p.plays+'回プレイ'));b.addEventListener('click',()=>{if(active&&!paused){pause();} select(i);if(matchMedia('(max-width:700px)').matches)$('play-area').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});});parent.append(b);});}
function formButtons(){const m=MODES[selected];$('forms').replaceChildren();m.forms.forEach((f,i)=>{const b=el('button',{class:'form-button'+(i===form?' selected':''),type:'button','aria-pressed':String(i===form)});b.append(el('strong',{},f.name),el('p',{},f.note),el('small',{},f.effect));b.addEventListener('click',()=>{if(active){if(!paused)pause();$('arena-status').textContent='育成タイプの変更は、次の挑戦から反映されます。';}form=i;formButtons();if(!active)ready();});$('forms').append(b);});}
function updateParts(){const isScrap=MODES[selected].id==='scrap';$('parts').hidden=!isScrap;if(!isScrap)return;const parts=run?.parts||(form===0?['cannon','cannon','shield']:['shield','shield','spike']);const names={cannon:'砲台',shield:'盾',spike:'トゲ'};$('part-buttons').replaceChildren();parts.forEach((part,i)=>{const b=el('button',{type:'button','data-slot':String(i)},['左','右','後'][i]+'：'+names[part]);b.addEventListener('click',()=>{if(run){cyclePart(run,i);updateParts();}});$('part-buttons').append(b);});}
function updateProgress(){const p=progress.modes[MODES[selected].id];$('materials').textContent=String(p.materials);$('upgrade').disabled=p.materials<3||p.level>=3;$('upgrade').replaceChildren(document.createTextNode(p.level>=3?'基礎成長 MAX':'基礎成長 '+p.level+'/3'),el('span',{},p.level>=3?'完成':'素材3'));$('upgrade-note').textContent=active?'購入した基礎成長は、次の挑戦から反映。':'最大3段階。次の挑戦で体力＋1、攻撃＋8%。';}
function select(index){history.replaceState(null,'','#'+MODES[index].id);selected=index;form=0;active=false;paused=false;showingResult=false;clearInput();run=createRun(MODES[index].id,form,progress.modes[MODES[index].id].level,142857);const m=MODES[index];document.documentElement.style.setProperty('--accent',m.color);$('game-en').textContent=m.n+' / '+m.en;$('game-title').textContent=m.title;$('game-description').textContent=m.description;$('action-label').textContent=m.action;$('action-hint').textContent='Space で'+m.action;$('lighten').hidden=m.id!=='grow';$('pause').disabled=true;$('pause').textContent='一時停止';$('tips').replaceChildren(...m.tips.map(t=>el('li',{},t)));$('test-question').textContent=m.test;$('memo').value=progress.modes[m.id].memo;$('memo-status').textContent='';document.querySelectorAll('[data-rating]').forEach(b=>{const yes=b.dataset.rating===progress.modes[m.id].rating;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});makeCards();formButtons();updateParts();updateProgress();ready();updateHud();}
function ready(){const m=MODES[selected];showingResult=false;run=createRun(m.id,form,progress.modes[m.id].level,142857);$('overlay').hidden=false;$('overlay-kicker').textContent='READY TO TRY?';$('overlay-title').textContent=m.tag;$('overlay-copy').textContent=m.forms[form].note;$('overlay-meta').textContent='移動＋'+m.action+' / 1回75秒\nボスを倒せばクリア。負けても素材＋2。';$('start').replaceChildren(document.createTextNode('このタイプで始める'),el('span',{},'↗'));$('change-form').hidden=true;$('arena-status').textContent='育て方を選んでスタート。';updateParts();updateHud();}
function start(){
 if(paused&&active){paused=false;$('overlay').hidden=true;$('pause').textContent='一時停止';$('arena-status').textContent='';clearInput();canvas.focus({preventScroll:true});return;}
 const m=MODES[selected];const previousParts=run?.mode===m.id&&run.form===form?[...run.parts]:null;run=createRun(m.id,form,progress.modes[m.id].level,142857);if(m.id==='scrap'&&previousParts)run.parts=previousParts;active=true;paused=false;endHandled=false;showingResult=false;clearInput();$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='一時停止';$('arena-status').textContent=m.id==='scrap'?'移動で体の向きを変え、部品を敵に向けよう。':m.id==='grow'?'緑の実に近づいて食べる。Qで軽くなれる。':m.id==='yoyo'?'投げた後に移動して、戻り道を変えよう。':'弾が触れる直前に反射。連打せずタイミングを。';updateParts();updateProgress();updateHud();canvas.focus({preventScroll:true});
}
function pause(){if(!active||paused)return;paused=true;clearInput();$('overlay').hidden=false;$('overlay-kicker').textContent='TAKE A BREATH';$('overlay-title').textContent='ひと休み中';$('overlay-copy').textContent='「続ける」で、同じ場所から再開します。';$('overlay-meta').textContent='育成タイプ・基礎成長の変更は次の挑戦から。';$('start').replaceChildren(document.createTextNode('続ける'),el('span',{},'↗'));$('change-form').hidden=false;$('change-form').textContent='この挑戦をやめて、育て方を選び直す';$('pause').textContent='再開';}
function result(){active=false;paused=false;showingResult=true;clearInput();bankRun(progress,run);save();makeCards();updateProgress();$('pause').disabled=true;$('overlay').hidden=false;const won=run.outcome==='win';$('overlay-kicker').textContent=won?'BOSS CLEARED!':'ONE MORE TRY?';$('overlay-title').textContent=won?'攻略、成功。':run.outcome==='time'?'時間切れ。':'もう少し、だった？';$('overlay-copy').textContent=won?'別の育て方でも、倒せるだろうか。':'育て方や動き方を変えて、試してみよう。';$('overlay-meta').textContent='ボスに与えたダメージ '+(run.boss.maxHp-run.boss.hp)+' / '+run.boss.maxHp+'\n素材 ＋'+run.endedReward+'　｜　挑戦 '+progress.modes[run.mode].plays+'回';$('start').replaceChildren(document.createTextNode('同じタイプでもう一回'),el('span',{},'↗'));$('change-form').hidden=false;$('change-form').textContent='育て方を選び直す';$('arena-status').textContent='下の「もう一回、遊びたい？」から感想を残せます。';endHandled=true;updateHud();}
function updateHud(){if(!run)return;const p=run.player;$('life').textContent='●'.repeat(Math.max(0,p.hp))+'○'.repeat(Math.max(0,p.maxHp-p.hp));$('life').setAttribute('aria-label','体力 '+p.hp+' / '+p.maxHp);$('timer').replaceChildren(document.createTextNode(String(Math.ceil(run.left))),el('span',{},'s'));$('boss-bar').style.width=(run.boss.hp/run.boss.maxHp*100)+'%';$('boss-hp').textContent=run.boss.hp+' / '+run.boss.maxHp;$('stage-label').textContent=active?(run.boss.hp<run.boss.maxHp*.5?'PHASE 02':'PHASE 01'):'TRAINING ARENA';let stats=[];if(run.mode==='reflect')stats=[['撃ち返し',run.reflections],['PERFECT',run.perfects],['反射',run.cooldown>0?'準備中':'READY']];if(run.mode==='yoyo')stats=[['戻りで命中',run.returnHits],['武器',run.weapon?(run.weapon.phase==='return'?'戻り中':'飛行中'):'手元']];if(run.mode==='scrap')stats=[['ダメージ',run.score],['突進',run.cooldown>0?'準備中':'READY'],['向き','移動方向']];if(run.mode==='grow'){const st=growthStats(run.form,run.growth);stats=[['成長',run.growth+'/10'],['移動速度',Math.round(st.speed)],['かみつき',Math.round(st.damage)]];}$('run-stats').replaceChildren(...stats.map(([key,value])=>{const e=el('span',{},key+' ');e.append(el('b',{},String(value)));return e;}));$('lighten').disabled=run.growth<=0;}
function clearInput(){input.keys.clear();input.padKeys.clear();input.joy={x:0,y:0};input.action=false;input.lighten=false;input.aim=null;joyPointer=null;joyOrigin=null;$('knob').style.transform='';$('action').classList.remove('pressed');}
function axisInput(){let x=input.joy.x,y=input.joy.y;const k=input.keys,p=input.padKeys;if(k.has('KeyA')||k.has('ArrowLeft')||p.has('left'))x--;if(k.has('KeyD')||k.has('ArrowRight')||p.has('right'))x++;if(k.has('KeyW')||k.has('ArrowUp')||p.has('up'))y--;if(k.has('KeyS')||k.has('ArrowDown')||p.has('down'))y++;return{x,y,aim:input.aim,action:input.action,lighten:input.lighten};}
function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.width*H/W*dpr);}
function frame(t){const dt=Math.min((t-lastFrame)/1000||0,1/30);lastFrame=t;
 if(run){if(active&&!paused){step(run,axisInput(),dt);input.action=false;input.lighten=false;if(run.events.length){const event=run.events.find(x=>['hurt','win','lose','reflect','eat','hit'].includes(x))||run.events[0];tone(event);}if(run.status==='ended'&&!endHandled)result();}draw(ctx,run,MODES[selected],{reduced,aim:input.aim});hudClock+=dt;if(hudClock>.12){updateHud();hudClock=0;}}
 requestAnimationFrame(frame);
}
function isTyping(e){return e.target instanceof HTMLElement&&(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable);}
document.addEventListener('keydown',e=>{if(isTyping(e))return;if(e.code==='Escape'){if(active){e.preventDefault();paused?start():pause();}return;}if(!active||paused)return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyQ'].includes(e.code)){e.preventDefault();if(e.code==='Space'){if(!e.repeat)input.action=true;}else if(e.code==='KeyQ'){if(!e.repeat)input.lighten=true;}else input.keys.add(e.code);}});
document.addEventListener('keyup',e=>input.keys.delete(e.code));
window.addEventListener('blur',()=>{if(active&&!paused)pause();else clearInput();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active&&!paused)pause();});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=canvas.getBoundingClientRect();input.aim={x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height};});
canvas.addEventListener('pointerleave',()=>input.aim=null);canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'&&active&&!paused){input.action=true;canvas.focus({preventScroll:true});}});
const pad=$('joystick');
pad.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();joyPointer=e.pointerId;pad.setPointerCapture(e.pointerId);const r=pad.getBoundingClientRect();joyOrigin={x:r.left+r.width/2,y:r.top+r.height/2};setJoy(e);});
function setJoy(e){if(e.pointerId!==joyPointer||!joyOrigin)return;const dx=e.clientX-joyOrigin.x,dy=e.clientY-joyOrigin.y,length=Math.hypot(dx,dy),limit=26,f=length>limit?limit/length:1;input.joy={x:dx*f/limit,y:dy*f/limit};$('knob').style.transform=`translate(${dx*f}px,${dy*f}px)`;input.aim=null;}
pad.addEventListener('pointermove',setJoy);for(const event of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(event,e=>{if(e.pointerId===joyPointer){joyPointer=null;joyOrigin=null;input.joy={x:0,y:0};$('knob').style.transform='';}});
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);input.padKeys.add(b.dataset.dir);input.aim=null;});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>input.padKeys.delete(b.dataset.dir));b.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){input.padKeys.add(b.dataset.dir);e.preventDefault();}});b.addEventListener('keyup',()=>input.padKeys.delete(b.dataset.dir));});
$('action').addEventListener('pointerdown',e=>{e.preventDefault();input.action=true;$('action').classList.add('pressed');$('action').setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('action').addEventListener(event,()=>$('action').classList.remove('pressed'));$('action').addEventListener('click',e=>{if(e.detail===0)input.action=true;});
$('lighten').addEventListener('click',()=>input.lighten=true);$('start').addEventListener('click',start);$('pause').addEventListener('click',()=>paused?start():pause());$('change-form').addEventListener('click',()=>{active=false;paused=false;clearInput();$('pause').disabled=true;$('pause').textContent='一時停止';ready();});
$('sound').addEventListener('click',async()=>{try{audio||=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();sound=!sound;$('sound').textContent=sound?'音 ON':'音 OFF';$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone('catch');}catch{$('sound').textContent='音声は利用不可';$('sound').disabled=true;}});
$('upgrade').addEventListener('click',()=>{if(upgrade(progress,MODES[selected].id)){save();updateProgress();if(!active)ready();}});
document.querySelectorAll('[data-rating]').forEach(b=>b.addEventListener('click',()=>{progress.modes[MODES[selected].id].rating=b.dataset.rating;document.querySelectorAll('[data-rating]').forEach(x=>{const yes=x===b;x.classList.toggle('selected',yes);x.setAttribute('aria-pressed',String(yes));});save();makeCards();$('memo-status').textContent=storageOK?'この端末に保存しました。':'保存できませんでした。';}));
$('memo').addEventListener('input',()=>{progress.modes[MODES[selected].id].memo=$('memo').value;save();$('memo-status').textContent=storageOK?'この端末に保存しました。':'保存できませんでした。';});
$('copy-feedback').addEventListener('click',async()=>{const text=MODES.map(m=>{const p=progress.modes[m.id];return m.n+' '+m.title+'\n感想：'+(p.rating||'未回答')+' / 挑戦：'+p.plays+'回 / クリア：'+p.wins+'回\nメモ：'+(p.memo||'なし');}).join('\n\n');try{await navigator.clipboard.writeText(text);$('copy-status').textContent='コピーしました。このチャットに貼り付けられます。';}catch{$('copy-status').textContent='コピーできませんでした。感想をこのチャットに直接入力してください。';}});
window.addEventListener('hashchange',()=>{const index=MODES.findIndex(m=>m.id===location.hash.slice(1));if(index>=0&&index!==selected)select(index);});
new ResizeObserver(resize).observe(canvas);select(Math.max(0,MODES.findIndex(m=>m.id===location.hash.slice(1))));resize();save();requestAnimationFrame(frame);
